from helpers import D, src, DSM, mk
from functools import partial
CARDS = []
X = partial(mk, "disruptive", "disruptive", "compass")
DSM_X = DSM("Disruptive, Impulse-Control, and Conduct Disorders")
NICE158 = src("src-nice-cg158", "Antisocial behaviour and conduct disorders in children and young people: recognition and management (CG158)", "NICE", "https://www.nice.org.uk/guidance/cg158", 2013, seen=True, note="April 2026 exceptional surveillance document listed; content not opened.")
KESSLER_IED = src("src-kessler-ied", "The prevalence and correlates of DSM-IV intermittent explosive disorder in the National Comorbidity Survey Replication", "Archives of General Psychiatry (Kessler et al.); summarized by Harvard Gazette", "https://news.harvard.edu/gazette/story/2006/06/under-diagnosed-rage-disorder-more-prevalent-than-previously-thought", 2006, seen=True)
KLEPTO_REV = src("src-klepto-rev", "Kleptomania: clinical features and treatment (review)", "PubMed Central", "https://pmc.ncbi.nlm.nih.gov/articles/PMC9567910", 2022, seen=True, note="Figures taken from a search snippet; article not opened.")
YM = src("src-youngminds-parents", "Parents Helpline", "YoungMinds (UK)", "https://www.youngminds.org.uk/parent/parents-helpline/", seen=True)
PARENT_COMMS = ["youngminds-parents-helpline", "family-lives-helpline", "chadd-online-communities", "nami-connection-and-helpline"]
X_NOTE = ["Behaviour labels carry stigma for children and families; wording reviewed for blame."]

CARDS.append(X("oppositional-defiant-disorder", "Oppositional Defiant Disorder", "When a child's anger and defiance take over family life", ["ODD"], "F91.3",
 "A lasting pattern of angry mood, arguing, and defiance toward adults that goes well beyond normal childhood pushback.",
 "All children argue, test limits, and lose their temper sometimes. Oppositional defiant disorder is a persistent pattern, lasting six months or more, of being angry or irritable, arguing and defying adults, and being spiteful, causing real problems at home or school. It usually shows up before age eight and is very often found alongside ADHD, anxiety, or learning difficulties. The best treatments work with parents and the child together, and most children improve.",
 ["Every request became a battle. Bedtime, homework, shoes. I was exhausted and ashamed, and I thought it was my parenting.", "Once we learned he wasn't choosing to be difficult, that his brain got flooded, we could actually help him.", "I'm 15. I know I argue with everything. I don't know how to stop once I've started."],
 ["Often loses temper, easily annoyed, or angry and resentful much of the time", "Argues with adults and refuses to follow rules or requests", "Deliberately annoys others and blames others for their mistakes", "Spiteful or vindictive behaviour at times", "Pattern lasting at least six months and causing problems at home or school"],
 [{"myth": "ODD is just bad parenting.", "fact": "Temperament, ADHD, anxiety, stress, and family circumstances all play a part. Parents didn't cause it, but parent-focused therapy is one of the most effective treatments."},
  {"myth": "A child with ODD is a bad kid who'll end up in trouble.", "fact": "Most children with ODD do not go on to conduct disorder or crime, especially with early support. Many are anxious, sensitive, or overwhelmed children."},
  {"myth": "Punishment harder and more often will fix it.", "fact": "Escalating punishment usually makes defiance worse. Predictable routines, praise for what goes well, and calm, consistent limits work far better."}],
 {"plain": "Roughly 3 in 100 children and teens have ODD, and estimates range from about 1 to 11 in 100 depending on the study. It's a bit more common in boys before puberty.", "figure": "About 3.3% average prevalence, range 1%–11% (DSM-5-TR text)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "The strongest evidence is for parent training programmes, in groups or one-to-one, that teach calm, consistent ways to respond to behaviour and to notice what's going well. Child-focused therapy builds problem-solving and emotion skills; family therapy helps older children and teens. Treating ADHD or anxiety when present often improves behaviour a lot. Medication isn't a treatment for ODD itself, though a doctor may prescribe and monitor it for co-occurring ADHD.",
  "evidence_based_options": ["Parent training programmes (for example, Incredible Years, Triple P, PCIT for younger children)", "Child and teen skills therapy for problem solving and emotion regulation", "Family-based therapy for older children and adolescents", "Treatment of co-occurring ADHD, anxiety, or learning difficulties"],
  "self_help_that_supports_care": ["Predictable routines and a few clear, calm rules", "Noticing and praising cooperative moments, however small", "Picking battles and avoiding power struggles", "Support for parents' own stress; this is hard work"],
  "guideline_refs": ["src-nice-cg158"]},
 "If a child's anger and defiance have gone on for months, are much worse than other children their age, and are harming family life or school, ask a doctor, school counsellor, or children's mental health service for an assessment. Earlier support makes a bigger difference.",
 "Normal toddler and teenage pushback, a reaction to a stressful change like divorce or bullying, trauma responses, autism-related distress, and ADHD impulsivity can all look like ODD. A good assessment looks at the whole picture.",
 "With the right support, most children with ODD grow into teens and adults who manage their anger and build good relationships.",
 ["conduct-disorder", "intermittent-explosive-disorder", "adhd", "disruptive-mood-dysregulation-disorder", "generalized-anxiety-disorder", "family-and-relationship-problems"],
 ["irritability", "emotional-dysregulation", "family-therapy", "school-support-plans", "comorbidity", "meltdown"],
 PARENT_COMMS, ("Soft line illustration of a parent and child sitting side by side on a doorstep, both calm, the child holding a football, the parent's hand resting lightly on the step. Pastel teal and warm orange.", "A parent and child sit calmly side by side on a doorstep."),
 [DSM_X, NICE158, YM], qs=["Find a primary prevalence citation.", "Check NICE CG158 April 2026 surveillance for changes."], notes=X_NOTE,
 young="ODD is a childhood and teenage diagnosis. For teens, the defiance often sits on top of anxiety, low self-esteem, or feeling misunderstood. Being listened to, not just corrected, is part of treatment.",
 strengths="Children described as oppositional are often persistent, independent-minded, and strong-willed, qualities that serve them well when channelled."))

CARDS.append(X("intermittent-explosive-disorder", "Intermittent Explosive Disorder", "Rage that arrives faster than thought", ["IED", "anger attacks", "rage disorder"], "F63.81",
 "Repeated outbursts of anger or aggression, far out of proportion to the trigger, that the person can't control.",
 "Intermittent explosive disorder is a pattern of sudden, intense outbursts: shouting, threats, breaking things, or physical fights, set off by small frustrations and far bigger than the situation deserves. The outbursts aren't planned, last less than about half an hour, and are followed by regret, embarrassment, or shame. It usually starts in the early teens and often runs alongside depression, anxiety, or substance use. Few people get treatment for it, but therapy and sometimes medication help a great deal.",
 ["It's like a switch flips. Thirty seconds later I'm looking at a broken door and I don't recognize the person who did it.", "I've lost two jobs and a relationship to my temper. I'm not a violent person. That's the part nobody believes.", "Therapy taught me to feel the heat rising before the explosion. That gap is everything."],
 ["Sudden verbal or physical outbursts, out of proportion to the trigger", "Outbursts are impulsive, not planned, and not for a goal", "Frequent smaller outbursts (about twice a week) or a few that cause damage or injury", "Regret, shame, or exhaustion afterwards", "Pattern that harms relationships, work, or leads to legal trouble"],
 [{"myth": "People with IED are just bad-tempered and need to try harder.", "fact": "IED involves a measurable difference in how the brain handles threat and frustration. Effort alone rarely fixes it; skills and treatment do."},
  {"myth": "It's rare.", "fact": "Around 1 in 14 US adults may meet criteria at some point. It's one of the most common and least treated mental health conditions."},
  {"myth": "Anger management classes are enough.", "fact": "Structured CBT for IED goes further than generic anger management, and medication prescribed by a doctor can help some people."}],
 {"plain": "A large US survey found that around 7 in 100 adults meet criteria for IED at some point, and about 4 in 100 in a given year. Only about a quarter ever get treatment for their anger.", "figure": "7.3% lifetime, 3.9% 12-month prevalence; 28.8% ever treated for anger (NCS-R, Kessler 2006)", "source_ref": "src-kessler-ied", "note": "Figures vary with definition; a narrower definition gives lower rates."},
 {"plain_summary": "Cognitive behavioural therapy designed for IED is the main treatment: learning to spot the early signs of rising anger, relaxation and cooling-down skills, changing the hostile interpretations that fuel outbursts, and practising calmer responses. Some people are helped by medication such as SSRIs or mood stabilizers, prescribed and monitored by a doctor. Treating co-occurring depression, PTSD, ADHD, or substance use matters. Partners and family can be included safely when it's appropriate.",
  "evidence_based_options": ["CBT for intermittent explosive disorder (individual or group)", "Relaxation, cooling-down, and cognitive skills training", "Medication (for example, SSRIs) prescribed and monitored by a doctor", "Treatment of co-occurring conditions including substance use"],
  "self_help_that_supports_care": ["Learning your early warning signs: heat, tight jaw, racing thoughts", "A time-out plan agreed in advance with the people you live with", "Less alcohol, more sleep; both lower the threshold for outbursts", "Repairing after an outburst, honestly, without excuses"],
  "guideline_refs": ["src-kessler-ied"]},
 "If outbursts are frightening you or the people around you, damaging relationships or work, or you've hurt someone or broken things, talk to a doctor or therapist. If someone is in immediate danger, call emergency services. If you're being hurt by someone else's anger, see the partner violence card and reach out.",
 "Being irritable when stressed, standing up for yourself, or planned aggression for gain aren't IED. Outbursts explained by mania, psychosis, intoxication, head injury, or a child's tantrums are assessed separately. Anger alone, without outbursts, isn't a disorder.",
 "People learn to catch the rising wave before it breaks. Many describe the first year without a blow-up as getting their relationships back.",
 ["oppositional-defiant-disorder", "conduct-disorder", "disruptive-mood-dysregulation-disorder", "posttraumatic-stress-disorder", "adhd", "partner-violence-and-adult-abuse"],
 ["impulsivity", "irritability", "emotional-dysregulation", "cbt", "trigger", "fight-flight-freeze-fawn"],
 ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia", "reddit-r-cptsd"],
 ("Soft line illustration of a person stepping outside onto a balcony at dusk, hand on the railing, taking a slow breath, a glass of water on a small table. Pastel teal and plum.", "A person stands on a balcony at dusk taking a slow breath."),
 [DSM_X, KESSLER_IED], qs=["Confirm the 12-month figure against the original paper.", "Add a treatment guideline source."], sens="elevated", notes=["Links to the partner violence card for people on the receiving end."],
 young="IED typically begins around age 12 to 14. In teens it's often mistaken for 'attitude' or ADHD alone. Early skills training helps before patterns set in."))

CARDS.append(X("conduct-disorder", "Conduct Disorder", "When a young person keeps breaking rules and hurting others", ["CD", "childhood-onset or adolescent-onset conduct disorder"], "F91.1 (childhood onset) / F91.2 (adolescent onset) / F91.9 (unspecified)",
 "A repeated pattern in a child or teen of aggression, destruction, lying, theft, or serious rule-breaking over a year.",
 "Conduct disorder is diagnosed in children and teens who keep breaking important rules for a year or more. That can mean fighting, cruelty, damaging property, lying, stealing, running away, or skipping school. It often grows out of ODD, ADHD, trauma, or a chaotic home. It is far more common among young people who have been abused or in care. Early, family-based help works. Most young people do not go on to adult problems.",
 ["He wasn't born like this. By the time anyone offered help he'd been excluded from three schools.", "I was angry at everyone, so I made sure everyone was scared of me. I was 13 and I'd never felt safe a day in my life.", "Multisystemic therapy was the first thing that treated us as a family instead of treating my son as a criminal."],
 ["Aggression toward people or animals: bullying, fighting, cruelty, or using weapons", "Destroying property or setting fires deliberately", "Lying, breaking in, or stealing", "Serious rule-breaking: staying out, running away, skipping school, before age 13", "Pattern over at least a year causing real harm or trouble"],
 [{"myth": "Conduct disorder means a child is a lost cause.", "fact": "Most young people with conduct disorder do not go on to adult antisocial behaviour, and the earlier the help, the better the outcome."},
  {"myth": "These kids need tougher punishment or boot camp.", "fact": "Research shows harsh, scare-based programmes don't work and can make things worse. Family and skills-based therapies do work."},
  {"myth": "It's purely the parents' fault.", "fact": "Genetics, early trauma, learning difficulties, poverty, neighbourhood, and peers all contribute. Blaming parents drives families away from the help that works."}],
 {"plain": "Around 4 in 100 children and teens have conduct disorder, by most estimates, more boys than girls. Rates are much higher among young people who've experienced abuse or care.", "figure": "About 4% median prevalence, range 2%–10% (DSM-5-TR text); nearly 40% of looked-after or abused children in a 2004 UK survey (NICE CG158 context)", "source_ref": "src-nice-cg158"},
 {"plain_summary": "NICE and other guidelines recommend parent training programmes for younger children, and for teens, family-based treatments such as multisystemic therapy or functional family therapy, which work with the whole family, school, and community. Child-focused skills therapy helps with problem solving and emotions. Co-occurring ADHD, depression, trauma, and learning difficulties are treated. Medication isn't a treatment for conduct disorder itself, and if used for aggression it's prescribed and monitored by a specialist.",
  "evidence_based_options": ["Parent training programmes for children aged roughly 3 to 11", "Multisystemic therapy or functional family therapy for adolescents", "Child-focused problem-solving and emotion skills programmes", "Treatment of ADHD, trauma, depression, or learning difficulties"],
  "self_help_that_supports_care": ["Keeping one trusted adult relationship steady, whatever happens", "Structure: school attendance, sport, something the young person is good at", "Parents getting their own support and respite", "Avoiding punishment that cuts the young person off from everyone"],
  "guideline_refs": ["src-nice-cg158"]},
 "If a child or teen is repeatedly aggressive, destructive, or in trouble with school or the law, ask a doctor, school, or children's mental health service for an assessment, and ask specifically about family-based treatments. If anyone is in immediate danger, call emergency services.",
 "A single serious incident, teenage rule-bending, behaviour that's a direct response to abuse or danger, or difficulties explained by autism, ADHD, or a learning disability aren't conduct disorder on their own.",
 "Many young people once labelled 'the problem kid' go on to steady work, families, and lives their younger selves couldn't picture.",
 ["oppositional-defiant-disorder", "intermittent-explosive-disorder", "antisocial-personality-disorder", "adhd", "child-abuse-and-neglect", "pyromania"],
 ["adverse-childhood-experiences", "family-therapy", "impulsivity", "trauma-informed", "school-support-plans", "risk-and-protective-factors"],
 PARENT_COMMS, ("Soft line illustration of a teenager and a coach fixing a bicycle together in a garage, tools laid out, afternoon light through the door. Pastel teal and rust.", "A teenager and a coach fix a bicycle together in a sunlit garage."),
 [DSM_X, NICE158, YM], qs=["Find a primary prevalence citation."], notes=X_NOTE, clin=True,
 subs=[{"title": "'With limited prosocial emotions' specifier", "icd10cm_code": "n/a", "text": "Added when a young person shows persistent lack of remorse, empathy, or concern about performance. It points to a need for more intensive, specialised support, not a verdict about character."}],
 young="This is a diagnosis of childhood and adolescence. Childhood onset (before 10) tends to be more persistent than adolescent onset; both respond to treatment."))

CARDS.append(X("pyromania", "Pyromania", "Deliberate fire-setting driven by tension and release", ["pathological fire-setting"], "F63.1",
 "Setting fires on purpose, more than once, because of tension before and relief or fascination after, not for gain.",
 "Pyromania is a rare impulse-control condition. A person sets fires on purpose more than once. They feel tension or excitement first, are fascinated by fire, and feel relief or pleasure during or after. The fires aren't set for money, revenge, or to hide a crime, and not because of drugs or delusions. Most fire-setting is not pyromania. The condition is poorly understood and often comes with other impulse or mood problems. Therapy focuses on urges and safety.",
 ["I'd feel it building for days. After the fire, calm, for a while. Then shame.", "It wasn't about hurting anyone. It was the fire itself. That's hard to explain to people, and I understand why."],
 ["More than one deliberate, purposeful fire", "Tension or excitement before setting the fire", "Fascination with fire, firefighting, and its effects", "Pleasure or relief when setting or watching fires", "Not done for money, revenge, concealment, or while intoxicated or delusional"],
 [{"myth": "Everyone who sets fires has pyromania.", "fact": "Pyromania is rare. Most fire-setting is linked to anger, crime, peer pressure, curiosity in children, or other conditions, not to this diagnosis."},
  {"myth": "People with pyromania are dangerous and beyond help.", "fact": "Therapy that targets urges, triggers, and safety planning helps, and the condition is treatable alongside any co-occurring problems."}],
 {"plain": "Pyromania is rare. Good population figures don't exist; among people who have set fires, only a small minority meet criteria.", "figure": "Lifetime prevalence not established; about 3% of adult fire-setters in some clinical samples (DSM-5-TR text)", "source_ref": "src-dsm", "note": "Needs a primary citation."},
 {"plain_summary": "There are no large treatment trials. Clinicians use cognitive behavioural approaches: identifying the build-up of tension, finding alternative outlets, learning to manage urges, and making a safety plan with the people around the person. Co-occurring mood, substance, or impulse conditions are treated, with any medication prescribed and monitored by a doctor. Fire-safety education programmes exist for children and teens who set fires.",
  "evidence_based_options": ["CBT focused on urges, triggers, and relapse prevention", "Fire-safety education programmes for young people", "Treatment of co-occurring mood, substance, or impulse conditions", "Family involvement and safety planning"],
  "self_help_that_supports_care": ["Noticing the tension building and telling someone", "Removing easy access to lighters and matches at home", "Alternative ways to release tension: exercise, cold water, movement", "Honest conversations with a therapist, free of judgement"],
  "guideline_refs": []},
 "If you or someone you know has set fires more than once and feels an urge or fascination that's hard to control, talk to a doctor or mental health professional. If there's any immediate danger from fire, call emergency services first.",
 "Children's curiosity about fire, fire set in anger, for insurance, to cover a crime, during intoxication, or because of a delusion aren't pyromania.",
 "Urges can be understood and managed. People do recover and keep themselves and others safe.",
 ["conduct-disorder", "kleptomania", "intermittent-explosive-disorder", "antisocial-personality-disorder"],
 ["impulsivity", "craving", "relapse-prevention", "cbt"],
 ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia"],
 ("Soft line illustration of a person sitting on a park bench with a therapist, notebook open, a fountain in the background, calm daylight. Pastel teal and grey. No fire.", "A person and a therapist sit on a park bench with a notebook open."),
 [DSM_X], qs=["Find a primary prevalence citation.", "Add a treatment reference."], notes=["No depictions of fire in illustrations; no description of fire-setting methods."], clin=True))

CARDS.append(X("kleptomania", "Kleptomania", "Stealing driven by urges, not need or greed", ["compulsive stealing"], "F63.2",
 "Repeatedly failing to resist urges to steal things you don't need, with tension before and relief after.",
 "Kleptomania is an impulse-control condition in which a person repeatedly can't resist urges to steal things they don't need and could usually afford. There's rising tension before, relief or a rush during, and often guilt and shame afterwards. The stealing isn't out of anger, revenge, or need. It's more common in women, often starts in the teens, and frequently comes with depression, anxiety, or other impulse or substance problems. People hide it for years. Therapy and sometimes medication help.",
 ["I've stolen things I threw away in the car park. It's never about the thing.", "I was terrified of being caught, and I still did it. Admitting it to a therapist was the first time anyone said it was a condition.", "The urge is like an itch that gets louder until you scratch it. Now I have ways to wait it out."],
 ["Repeated failure to resist urges to steal unneeded items", "Rising tension before the act", "Pleasure, relief, or gratification when stealing", "Not done out of anger, revenge, need, or delusion", "Guilt, shame, and fear of being caught afterwards"],
 [{"myth": "Kleptomania is an excuse rich people use when they're caught shoplifting.", "fact": "Most shoplifting isn't kleptomania. The condition involves real, distressing urges and usually deep shame, and it's rare."},
  {"myth": "It's just a bad habit; stop doing it.", "fact": "People with kleptomania often try desperately to stop. Treatment that targets urges works far better than willpower alone."}],
 {"plain": "Kleptomania is rare, affecting well under 1 in 100 people. It's thought to be more common in women, and it's found more often among people arrested for shoplifting.", "figure": "About 0.3%–0.6% of the general population (DSM-5-TR text); a 2022 review gives 0.6%–0.8%", "source_ref": "src-klepto-rev"},
 {"plain_summary": "Evidence is limited but growing. Cognitive behavioural therapy helps people recognize the build-up of urges, use delay and replacement strategies, and change the thoughts around stealing; covert sensitisation and imaginal desensitisation are often used. One placebo-controlled trial found naltrexone, a medication that dampens the reward of the act, reduced urges and stealing; it's prescribed and monitored by a doctor. Treating co-occurring depression, anxiety, or substance use is important.",
  "evidence_based_options": ["CBT for impulse control, including urge-management techniques", "Naltrexone prescribed and monitored by a doctor (one small controlled trial)", "Treatment of co-occurring depression, anxiety, or substance use", "Support groups for impulse-control and compulsive behaviours"],
  "self_help_that_supports_care": ["Shopping with someone, or avoiding shops when urges are high", "Delaying: waiting ten minutes when the urge hits, then re-deciding", "Tracking urges, triggers, and what helped", "Telling one trusted person so it's no longer a secret"],
  "guideline_refs": ["src-klepto-rev"]},
 "If you keep stealing things you don't need and can't seem to stop, especially if there's a build-up of tension and relief, talk to a doctor or therapist. Kleptomania is a recognized condition and clinicians have heard it before. Legal advice is separate from treatment; get both if you need them.",
 "Ordinary shoplifting for gain, dares, stealing in anger or protest, theft linked to mania, psychosis, or dementia, and stealing to fund a substance use disorder aren't kleptomania.",
 "Urges fade with treatment. People stop living in fear of the next shop door.",
 ["pyromania", "intermittent-explosive-disorder", "obsessive-compulsive-disorder", "gambling-disorder", "major-depressive-disorder"],
 ["impulsivity", "craving", "compulsion", "cbt", "relapse-prevention"],
 ["nami-connection-and-helpline", "mind-side-by-side", "sane-forums-australia"],
 ("Soft line illustration of a person pausing at a shop doorway, checking a note on their phone, a friend waiting outside with two coffees. Pastel teal and lavender.", "A person pauses at a shop doorway checking their phone while a friend waits with two coffees."),
 [DSM_X, KLEPTO_REV], qs=["Open the 2022 review to confirm prevalence and treatment statements."], notes=["Wording avoids moral judgement; legal context acknowledged without advice."]))
